<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    body { max-width: 48rem; margin: 3rem auto; padding: 0 1rem; font: 16px/1.5 system-ui, sans-serif; color: #172033; }
    h1 { margin-bottom: 1.5rem; }
    form { display: flex; gap: .6rem; align-items: end; flex-wrap: wrap; }
    label { display: grid; gap: .25rem; }
    input, button { font: inherit; padding: .55rem .75rem; }
