    #alert { color: #a12622; min-height: 1.5em; }
    #projects { list-style: none; padding: 0; margin-top: 1rem; }
    .project-row { border-top: 1px solid #d8deea; padding: .85rem 0; display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
  </style>
</head>
<body>
  <main>
    <h1>Workboard</h1>
    <form id="create-form">
      <label>Project name<input id="project-name" name="name" type="text" autocomplete="off"></label>
      <button type="submit">Create project</button>
    </form>
    <p id="alert" role="alert" aria-live="polite"></p>
    <ul id="projects" aria-label="Projects"></ul>
  </main>
  <script type="module">
    const list = document.querySelector('#projects');
    const alertBox = document.querySelector('#alert');
    async function loadProjects() {
      const response = await fetch('/api/projects');
      const projects = await response.json();
      list.replaceChildren(...projects.map(project => {
        const row = document.createElement('li');
        row.className = 'project-row';
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = 'Open project';
        button.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
        row.append(name, button);
        return row;
      }));
    }
    document.querySelector('#create-form').addEventListener('submit', async event => {
      event.preventDefault();
      alertBox.textContent = '';
      const name = document.querySelector('#project-name').value.trim();
      if (!name) { alertBox.textContent = 'Project name is required'; return; }
      const response = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
      if (!response.ok) { const error = await response.json(); alertBox.textContent = error.error || 'Unable to create project'; return; }
      document.querySelector('#project-name').value = '';
      await loadProjects();
    });
    loadProjects();
  </script>
</body>
</html>
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Project · Workboard</title>
  <style>
    body { max-width: 48rem; margin: 3rem auto; padding: 0 1rem; font: 16px/1.5 system-ui, sans-serif; color: #172033; }
    button { font: inherit; padding: .55rem .75rem; cursor: pointer; }
    form { display: flex; gap: .6rem; align-items: end; flex-wrap: wrap; margin-top: 1rem; }
    label { display: grid; gap: .25rem; }
    input, select { font: inherit; padding: .55rem .75rem; }
    #alert { color: #a12622; min-height: 1.5em; }
    #tasks { list-style: none; padding: 0; }
    .task-row { border-top: 1px solid #d8deea; padding: .85rem 0; display: flex; align-items: center; gap: .65rem; }
  </style>
</head>
<body>
  <main>
    <button id="back" type="button">Projects</button>
    <h1 id="project-name"></h1>
    <p id="missing" role="alert" hidden>Project not found</p>
    <section id="task-section" hidden aria-label="Tasks">
      <form id="create-form">
        <label>Task title<input id="task-title" name="title" type="text" autocomplete="off"></label>
        <button type="submit">Create task</button>
      </form>
      <p id="alert" role="alert" aria-live="polite"></p>
      <label>Task filter<select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label>
      <ul id="tasks" aria-label="Tasks"></ul>
    </section>
  </main>
  <script type="module">
    document.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    const id = window.location.pathname.split('/').pop();
    const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
    if (response.ok) {
      const project = await response.json();
      document.querySelector('#project-name').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      document.querySelector('#task-section').hidden = false;
      const taskList = document.querySelector('#tasks');
      const filter = document.querySelector('#task-filter');
      async function loadTasks() {
        const taskResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
        const tasks = await taskResponse.json();
        const visible = tasks.filter(task => filter.value === 'All' || (filter.value === 'Open' ? !task.completed : task.completed));
        taskList.replaceChildren(...visible.map(task => {
          const row = document.createElement('li');
          row.dataset.testid = 'task-row';
          row.className = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
            await loadTasks();
          });
          const title = document.createElement('span');
          title.textContent = task.title;
          row.append(checkbox, title);
          return row;
        }));
      }
      filter.addEventListener('change', loadTasks);
      document.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const alertBox = document.querySelector('#alert');
        alertBox.textContent = '';
        const title = document.querySelector('#task-title').value.trim();
        if (!title) { alertBox.textContent = 'Task title is required'; return; }
        const createResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
        if (!createResponse.ok) { const error = await createResponse.json(); alertBox.textContent = error.error || 'Unable to create task'; return; }
        document.querySelector('#task-title').value = '';
        await loadTasks();
      });
      await loadTasks();
    } else {
      document.querySelector('#missing').hidden = false;
    }
  </script>
</body>
</html>
